import {
  Group,
  Mesh,
  PlaneGeometry,
  MeshBasicNodeMaterial,
} from 'three/webgpu';

export default function createNode(config, ctx) {
  const group = new Group();

  // --- Plane (sprite) with texture from atlas region ---
  const srcRect = { x: 0, y: 0, w: 512, h: 320 };
  const aspect = srcRect.w / srcRect.h;
  const geometry = new PlaneGeometry(1.6, 1);

  const material = new MeshBasicNodeMaterial({
    transparent: true,
    side: ctx.THREE.DoubleSide,
  });

  const plane = new Mesh(geometry, material);
  group.add(plane);

  // Load texture and apply atlas offset/repeat
  const texturePromise = ctx.textureLoader.loadTexture(config.imageUrl);
  texturePromise.then((tex) => {
    const img = tex.image;
    if (img) {
      const tw = img.width;
      const th = img.height;
      const repeatU = srcRect.w / tw;
      const repeatV = srcRect.h / th;
      tex.repeat.set(repeatU, repeatV);
      tex.offset.set(srcRect.x / tw, srcRect.y / th);
    } else {
      tex.repeat.set(1, 1);
      tex.offset.set(0, 0);
    }
    tex.needsUpdate = true;
    material.map = tex;
    material.needsUpdate = true;
  });

  // --- Text content from config ---
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    const textMesh = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize || 39,
      color: '#e8ecf2',
      align: 'center',
      maxWidthPx: 190,
    });
    if (textMesh) {
      textMesh.position.set(0, 0, 0.005);
      group.add(textMesh);
    }
  }

  // --- Scene placement ---
  group.position.set(3.2, 1, 0.06);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  // --- Cleanup ---
  const geometryRef = geometry;
  const materialRef = material;
  group.userData.cleanup = () => {
    geometryRef.dispose();
    materialRef.dispose();
  };

  group.userData.handlers = {};

  return group;
}
